package com.acme.payments;

import com.acme.payments.domain.AuthorizeRequest;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.annotation.Transactional;

import java.lang.reflect.Method;

import static org.junit.jupiter.api.Assertions.assertNull;

class PaymentServiceTransactionTest {

    // Regression for inc-001: PR#482 put fraudClient.score() inside a
    // @Transactional authorize(), holding a Hikari connection for the full
    // (degraded, ~8s) fraud call and exhausting the 10-connection pool.
    // Fails before the fix (annotation present), passes after it is removed
    // and persistence is done via short per-save repository transactions.
    @Test
    void authorizeMustNotHoldDbTransactionAcrossRemoteFraudCall() throws Exception {
        Method authorize = PaymentService.class.getMethod("authorize", AuthorizeRequest.class);
        assertNull(authorize.getAnnotation(Transactional.class),
            "authorize() must not be @Transactional: fraudClient.score() and "
            + "gateway.authorize() are remote calls that would hold a DB "
            + "connection for their full duration and exhaust the Hikari pool");
    }
}

